import { useEffect, useState } from 'preact/hooks';
import { traitsOf } from '../shared/traits';
import type { EconomyBreakdown } from '../shared/protocol';
import type { NationStat, TechInfo } from '../shared/protocol';
import { ActionsTab, type ActionsTabProps } from './ActionsTab';
import { GodTab, type GodTabProps } from './GodTab';
import { displayName, t, type MessageKey } from './i18n';
import { allianceTitle } from './historyText';

export { displayName };

const hex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;
const num = (v: number): string => Math.round(v).toLocaleString('en-US');
const signed = (v: number): string => (v >= 0 ? '+' : '−') + num(Math.abs(v));

type Tab = 'overview' | 'economy' | 'actions' | 'god';

/**
 * Left nation panel (PLAN 1.31a): the selected nation's name and colour, then an Overview tab
 * (land, army, alliance, overlord or puppets, enemies) and an Economy tab (income, expenses,
 * balance, treasury, bonus, manpower; what it is researching, PLAN 3.1e). Nation chips select that nation. Actions (bonus −/+,
 * war, peace…) arrive with God Mode and player control (PLAN 1.32/1.33).
 */
export interface ControlProps {
  /** Whether the player controls this nation (PLAN 1.33a). */
  controlled: boolean;
  onTake: () => void;
  onRelease: () => void;
}

export function NationPanel({
  nation,
  byId,
  techs,
  onSelect,
  onChip,
  god,
  control,
  actions,
  flagUrl,
  economy,
  onEconomy,
  onHero,
}: {
  nation: NationStat;
  byId: Map<number, NationStat>;
  /** The scenario's techs, for the names and prices of what the nation is researching (PLAN 3.1e). */
  techs: readonly TechInfo[];
  onSelect: (id: number) => void;
  /** A click on a nation chip (PLAN 7.175f): its menu by the chip, at its bottom-left corner (page px); without, it selects the nation. */
  onChip?: ((id: number, x: number, y: number) => void) | null;
  god?: Omit<GodTabProps, 'nation'> | null;
  control?: ControlProps | null;
  /** Actions of the controlled nation (PLAN 1.33b); only for the nation the player controls. */
  actions?: Omit<ActionsTabProps, 'nation'> | null;
  /** The nation's flag as an image URL (PLAN 1.37b). */
  flagUrl?: string | null;
  /** Its month in parts (PLAN 7.4f34), asked for by `onEconomy(nation)` while the economy tab is open (0: closed). */
  economy?: EconomyBreakdown | null;
  onEconomy?: (nation: number) => void;
  /** A click on a living hero's row (PLAN 7.184c): its formation opened on the map and followed. */
  onHero?: ((formation: number) => void) | null;
}) {
  const [chosen, setTab] = useState<Tab>('overview');
  // The God tab exists only in God Mode (PLAN 1.32b).
  const tab: Tab = (!god && chosen === 'god') || (!actions && chosen === 'actions') ? 'overview' : chosen;
  const tabs: Tab[] = ['overview', 'economy', ...(actions ? (['actions'] as const) : []), ...(god ? (['god'] as const) : [])];
  // The month in parts is asked for while the economy tab is open, of this nation.
  useEffect(() => {
    onEconomy?.(tab === 'economy' ? nation.id : 0);
  }, [tab, nation.id]);
  useEffect(() => () => onEconomy?.(0), []);
  const chip = (id: number) => {
    const n = byId.get(id);
    return (
      <button
        key={id}
        class="nation-chip"
        data-testid="nation-chip"
        data-nation={id}
        onClick={(e) => {
          const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
          if (onChip) onChip(id, r.left, r.bottom - 8);
          else onSelect(id);
        }}
      >
        <span class="chip-swatch" style={{ background: hex(n?.color ?? 0x777777) }} />
        {n ? displayName(n.name) : `#${id}`}
      </button>
    );
  };
  const row = (label: MessageKey, value: string, testid?: string) => (
    <div class="panel-row">
      <span>{t(label)}</span>
      <span data-testid={testid}>{value}</span>
    </div>
  );
  return (
    <aside class="nation-panel" data-testid="nation-panel" data-nation={nation.id}>
      <header class="panel-head">
        {flagUrl ? <img class="panel-flag" data-testid="nation-flag" src={flagUrl} alt="" width={36} height={24} /> : <span class="panel-swatch" style={{ background: hex(nation.color) }} />}
        <span class="panel-name" data-testid="nation-name">
          {displayName(nation.name)}
        </span>
        <button class="panel-close" data-testid="nation-close" aria-label={t('panel.close')} onClick={() => onSelect(0)}>
          ×
        </button>
      </header>
      {control ? (
        control.controlled ? (
          <button type="button" class="god-btn panel-control" data-testid="release-control" onClick={control.onRelease}>
            {t('player.release')}
          </button>
        ) : (
          <button type="button" class="god-btn panel-control" data-testid="take-control" onClick={control.onTake}>
            {t('player.take')}
          </button>
        )
      ) : null}
      <nav class="panel-tabs">
        {tabs.map((k) => (
          <button key={k} class={tab === k ? 'tab active' : 'tab'} data-testid={`tab-${k}`} onClick={() => setTab(k)}>
            {t(`panel.${k}` as MessageKey)}
          </button>
        ))}
      </nav>
      {tab === 'actions' && actions ? (
        <ActionsTab nation={nation} {...actions} />
      ) : tab === 'god' && god ? (
        <GodTab nation={nation} {...god} />
      ) : tab === 'overview' ? (
        <section data-testid="panel-overview">
          {nation.heroes && nation.heroes.length > 0 ? (
            // Its heroes first (PLAN 7.184c): each its name and its health, or the days until it is back.
            <div class="panel-block panel-heroes" data-testid="panel-heroes">
              <div class="panel-sub">{t('panel.heroes')}</div>
              {nation.heroes.map((h, k) => {
                const name = t(h.nameKey as MessageKey);
                const pct = Math.round(h.health * 100);
                return (
                  <button
                    key={k}
                    type="button"
                    class="panel-row hero-row"
                    data-testid="hero-row"
                    data-formation={h.formation}
                    disabled={h.formation === 0 || !onHero}
                    title={h.formation !== 0 ? t('panel.heroOpen', { name }) : undefined}
                    onClick={() => h.formation !== 0 && onHero?.(h.formation)}
                  >
                    <span class="hero-name">{name}</span>
                    {h.returnDays === null ? (
                      <span class="hero-health" data-testid="hero-health">
                        <span class="hero-bar">
                          <span class={pct > 50 ? 'hero-fill' : pct > 25 ? 'hero-fill warn' : 'hero-fill low'} style={{ width: `${pct}%` }} />
                        </span>
                        {pct}%
                      </span>
                    ) : (
                      <span class="hero-return" data-testid="hero-return">
                        {h.returnDays === 0 ? t(h.waits === 'revival' ? 'panel.heroWaitsRevival' : h.waits === 'port' ? 'panel.heroWaitsPort' : 'panel.heroWaits') : h.returnDays === 1 ? t('panel.heroReturnsOne') : t('panel.heroReturns', { n: h.returnDays })}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          ) : null}
          {nation.traits !== 0 ? (
            // Its traits (ROADMAP R16), each with what it does on hover.
            <div class="panel-traits" data-testid="panel-traits">
              {traitsOf(nation.traits).map((tr) => (
                <span key={tr.id} class="trait-chip" data-testid="trait-chip" data-trait={tr.id} title={t(tr.descKey as MessageKey)}>
                  {t(tr.nameKey as MessageKey)}
                </span>
              ))}
            </div>
          ) : null}
          {row('panel.land', num(nation.area), 'stat-land')}
          {row('panel.landShare', `${(nation.landShare * 100).toFixed(1)}%`, 'stat-land-share')}
          {row('panel.army', `${num(nation.men)} (${nation.formations})`, 'stat-army')}
          {nation.warheads > 0 ? row('panel.warheads', num(nation.warheads), 'stat-warheads') : null}
          {nation.restraint ? (
            // Why a holder at war does not strike (PLAN 7.37f), in its war that weighs most.
            <div class="panel-note" data-testid="nation-restraint" data-reason={nation.restraint.reason}>
              {t(`panel.restraint.${nation.restraint.reason}` as MessageKey, { name: displayName(nation.name), by: displayName(byId.get(nation.restraint.by)?.name ?? '') })}
            </div>
          ) : null}
          {nation.nukeDead > 0 || nation.fallout > 0 ? (
            <div class="panel-block" data-testid="panel-nuclear">
              <div class="panel-sub">{t('panel.nuclearAge')}</div>
              {row('panel.nukeDead', num(nation.nukeDead), 'stat-nuke-dead')}
              {row('panel.falloutCells', num(nation.fallout), 'stat-fallout')}
            </div>
          ) : null}
          {nation.aircraft > 0 || nation.airLost > 0 || nation.bombed > 0 ? (
            <div class="panel-block" data-testid="panel-air">
              <div class="panel-sub">{t('panel.airWar')}</div>
              {row('panel.aircraft', `${num(nation.aircraft)} (${nation.wings})`, 'stat-aircraft')}
              {row('panel.airLost', num(nation.airLost), 'stat-air-lost')}
              {row('panel.bombed', num(nation.bombed), 'stat-bombed')}
            </div>
          ) : null}
          {row('panel.efficiency', `${Math.round(nation.efficiency * 100)}%`)}
          {nation.alliance ? (
            <div class="panel-block" data-testid="panel-alliance">
              <div class="panel-sub" data-testid="alliance-title">{allianceTitle(nation.alliance.name, (byId.get(nation.alliance.founder) ?? byId.get(nation.alliance.leader))?.name ?? null)}</div>
              {row('panel.unity', num(nation.alliance.unity))}
              {nation.alliance.leader !== nation.id ? row('panel.allianceLoyalty', num(nation.alliance.loyalty)) : null}
              {/* Its allies (the user's request, ADR-768): the other members, the leader first. */}
              <div class="panel-sub panel-sub-inner">{t('panel.allies')}</div>
              <div class="chips" data-testid="panel-allies">
                {nation.alliance.members.filter((m) => m !== nation.id).map(chip)}
              </div>
            </div>
          ) : null}
          {nation.overlord !== 0 ? (
            <div class="panel-block" data-testid="panel-overlord">
              <div class="panel-sub">{t('panel.overlord')}</div>
              <div class="chips">{chip(nation.overlord)}</div>
              {row('panel.autonomy', num(nation.autonomy))}
              {row('panel.loyalty', num(nation.loyalty))}
              {row('panel.integration', `${num(nation.integration)}%`)}
            </div>
          ) : null}
          {nation.puppets.length > 0 ? (
            <div class="panel-block" data-testid="panel-puppets">
              <div class="panel-sub">{t('panel.puppets')}</div>
              <div class="chips">{nation.puppets.map(chip)}</div>
            </div>
          ) : null}
          {nation.guarantees.length > 0 ? (
            <div class="panel-block" data-testid="panel-guarantees">
              <div class="panel-sub">{t('panel.guarantees')}</div>
              <div class="chips">{nation.guarantees.map(chip)}</div>
            </div>
          ) : null}
          {nation.guarantors.length > 0 ? (
            <div class="panel-block" data-testid="panel-guarantors">
              <div class="panel-sub">{t('panel.guarantors')}</div>
              <div class="chips">{nation.guarantors.map(chip)}</div>
            </div>
          ) : null}
          <div class="panel-block" data-testid="panel-wars">
            <div class="panel-sub">{t('panel.atWarWith')}</div>
            {nation.enemies.length > 0 ? <div class="chips">{nation.enemies.map(chip)}</div> : <div class="panel-note">{t('panel.atPeace')}</div>}
          </div>
        </section>
      ) : (
        <section data-testid="panel-economy">
          {row('panel.income', num(nation.income), 'stat-income')}
          {row('panel.expenses', num(nation.expenses), 'stat-expenses')}
          {row('panel.balance', signed(nation.income - nation.expenses), 'stat-balance')}
          {row('panel.gold', num(nation.gold), 'stat-gold')}
          {row('panel.incomeBonus', `${nation.incomeBonus >= 0 ? '+' : ''}${nation.incomeBonus}%`)}
          {row('panel.manpower', num(nation.manpower), 'stat-manpower')}
          {nation.bankrupt ? <div class="panel-warn">{t('panel.bankrupt')}</div> : null}
          {economy ? (
            // The month in parts (PLAN 7.4f34, the critic's N14): where the income comes from and
            // what the war takes of it; where the gold goes. A part that is nothing is left out.
            <div class="panel-block" data-testid="panel-month">
              <div class="panel-sub">{t('panel.incomeFrom')}</div>
              {(
                [
                  ['ownLand', 1],
                  ['occupiedLand', 1],
                  ['bonuses', 1],
                  ['blockade', -1],
                  ['convoys', -1],
                  ['bombs', -1],
                  ['fallout', -1],
                ] as const
              ).map(([k, sign]) => (Math.round(economy[k]) !== 0 || k === 'ownLand' ? <div key={k}>{row(`panel.econ.${k}` as MessageKey, sign < 0 ? signed(-economy[k]) : k === 'bonuses' ? signed(economy[k]) : num(economy[k]), `econ-${k}`)}</div> : null))}
              <div class="panel-sub">{t('panel.spentOn')}</div>
              {(['army', 'navy', 'air', 'admin', 'warheads'] as const).map((k) => (Math.round(economy[k]) !== 0 || k === 'army' ? <div key={k}>{row(`panel.econ.${k}` as MessageKey, num(economy[k]), `econ-${k}`)}</div> : null))}
            </div>
          ) : null}
          <div class="panel-block" data-testid="panel-research">
            <div class="panel-sub">{t('panel.research')}</div>
            {row('panel.researchBudget', num(nation.research), 'research-budget')}
            {nation.lines.length > 0 ? (
              nation.lines.map((l) => {
                const tech = techs[l.tech];
                return (
                  <div key={l.tech} class="panel-row" data-testid="research-line">
                    <span>{tech ? t(tech.nameKey as MessageKey) : `#${l.tech}`}</span>
                    <span data-testid="research-paid">{tech && tech.gold > 0 ? Math.floor((100 * l.paid) / tech.gold) : 0}%</span>
                  </div>
                );
              })
            ) : (
              <div class="panel-note">{t('panel.researchNone')}</div>
            )}
          </div>
        </section>
      )}
    </aside>
  );
}
