/**
 * T0 strategic counters (SPEC §8, PLAN 2.2): formations aggregated per nation per cell of a
 * world-aligned grid, one counter each showing Σ strength.
 *
 * Clustering is stable and multi-level: level L uses a grid of 2^L cells, so the grids nest
 * and a level-L+1 cluster is exactly the union of its level-L children. The level follows the
 * zoom so that a grid cell is about CLUSTER_PX on screen, with ±0.15 hysteresis.
 *
 * When the level changes, the finer level's counters animate over SPLIT_MS: from the parent's
 * centroid to their own when splitting, and from their own to the parent's when merging. At
 * the end they are replaced by the target level, already at the same positions. No counter
 * appears or disappears anywhere except under a counter in the same place.
 */
import { progress, running } from '../timing';
import { Ball2dCache, drawBall2dCached } from './ball2d';
import { HERO_SCALE } from './ballShader';
import { strengthText } from './markers';
import { worldToScreen, itemOffsets, type Camera, type MapGeometry } from '../camera';

export interface CounterSource {
  x: number;
  y: number;
  /** The nation, plus `NAVAL` for a fleet (`counterNation`): fleets are counters of their own (PLAN 4.10a). */
  nation: number;
  strength: number;
}

/**
 * Added to a fleet's nation in a counter (PLAN 4.10a): fleets cluster and fold among themselves
 * apart from armies, as another nation's would, and are drawn as a navy's (`counterNation`).
 */
export const NAVAL = 1 << 16;

/** A counter's nation as a source gives it: `nation` + NAVAL for a fleet. */
/** The radius of a counter's ball in the ball look, CSS px (before the unit size; PLAN 7.174f). */
export const COUNTER_BALL_R = 8;

export function counterNation(nation: number, fleet: boolean): number {
  return fleet ? nation + NAVAL : nation;
}

export interface Cluster {
  nation: number;
  gx: number;
  gy: number;
  /** Centroid in cells. */
  x: number;
  y: number;
  strength: number;
  count: number;
}

export interface DrawnCounter {
  key: string;
  nation: number;
  /** A navy's counter (PLAN 4.10a). */
  naval: boolean;
  /** World position in cells (as drawn, after animation). */
  wx: number;
  wy: number;
  alpha: number;
  /** The strength shown: with everything folded into this counter (PLAN 1.45b). */
  strength: number;
  text: string;
  /** Other nations folded into it (shown as "+n"). */
  others: number;
  /**
   * On its way into a neighbour (PLAN 1.45b): fading out where it stands, so its box lies on
   * or by its neighbour's. A fade starts at full opacity: in its first frame `alpha` is still 1.
   */
  folded: boolean;
  /** Its box on screen, CSS px (the first copy drawn, on a looping map). */
  x: number;
  y: number;
  w: number;
  h: number;
  /** A hero's own counter (PLAN 7.184b3): its formation, the first of those folded into it. */
  hero?: number;
  /** The heroes a hero's counter stands for (ROADMAP R8), in the order a click opens them. */
  heroes?: number[];
}

/** A hero at T0 (PLAN 7.184b3): its own counter, HERO_SCALE × a nation's, with its name. */
export interface HeroCounter {
  id: number;
  nation: number;
  naval: boolean;
  x: number;
  y: number;
  name: string;
}

export const CLUSTER_PX = 64;
export const HYSTERESIS = 0.15;
export const SPLIT_MS = 250;
export const MAX_LEVEL = 14;

/** The clustering level for `scale` CSS px per cell, keeping `current` within its hysteresis band. */
export function clusterLevel(scale: number, current: number | null): number {
  const lv = Math.log2(CLUSTER_PX / scale);
  const clamp = (l: number): number => Math.max(0, Math.min(MAX_LEVEL, l));
  if (current === null) return clamp(Math.round(lv));
  if (lv > current + 0.5 + HYSTERESIS || lv < current - 0.5 - HYSTERESIS) return clamp(Math.round(lv));
  return current;
}

export const clusterKey = (nation: number, level: number, gx: number, gy: number): string => `${nation}:${level}:${gx}:${gy}`;

/** Clusters at `level`, keyed by `clusterKey`. */
export function buildClusters(src: readonly CounterSource[], level: number): Map<string, Cluster> {
  const g = 2 ** level;
  const out = new Map<string, Cluster>();
  for (const f of src) {
    const gx = Math.floor(f.x / g);
    const gy = Math.floor(f.y / g);
    const k = clusterKey(f.nation, level, gx, gy);
    let c = out.get(k);
    if (!c) out.set(k, (c = { nation: f.nation, gx, gy, x: 0, y: 0, strength: 0, count: 0 }));
    c.x += f.x;
    c.y += f.y;
    c.strength += f.strength;
    c.count++;
  }
  for (const c of out.values()) {
    c.x /= c.count;
    c.y /= c.count;
  }
  return out;
}

const ease = (t: number): number => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);

/** A counter for the declutter pass: where it is in px (cells × scale: the camera's place does not matter) and what it holds. */
export interface FoldItem {
  key: string;
  nation: number;
  x: number;
  y: number;
  strength: number;
}

/** A counter after the declutter pass. */
export interface Fold {
  /** The counter this one is folded into; null = it is shown. */
  into: string | null;
  /** Shown counters: the strength with everything folded in, and how many other nations that is. */
  total: number;
  others: number;
  /** The counter of its own nation that stands for it (itself, unless it folded into one in the first pass). */
  lead: string;
  /** What it holds of its own nation, when it is its own lead: itself and those it stands for. */
  own: number;
}

export const FOLD_MS = 250;
/** Shown boxes keep this many px between them. */
export const FOLD_GAP_PX = 2;
/** A folded counter comes out again only once it clears its neighbour by this much more (no flicker at the edge). */
export const FOLD_HOLD_PX = 6;
/** The frame of a step of the zoom folds at most this many times more, each time with the hold of the fold before. */
const STEP_ROUNDS = 4;
/** Px between a counter's strength and its "+n". */
const BADGE_GAP = 4;
/** A counter with a new key within this many px of one of its nation takes over that one's fold state. */
const INHERIT_PX = 6;

/**
 * Screen-space declutter (PLAN 1.45b): no two counter boxes overlap. A counter whose box would
 * touch a stronger one's is folded into it (the nearest, when several): the stronger counter
 * shows the sum and how many other nations it took in. Nothing is dropped, so the shown counters
 * still add up to every formation's strength. A box grows with its text, so each pass repeats
 * until no box touches another.
 *
 * Two passes. First a nation's own counters fold into each other, strongest first. Then the
 * counters left fold across nations, in the order of what they now hold. So the children of a
 * cluster, standing on its centroid at the end of a merge animation, count exactly as the
 * cluster that replaces them, and the outcome does not change with the swap.
 *
 * `boxOf(total, others)` is a box's width and height in px. `held(key)` is true for a counter that
 * is folded already: it stays so until it clears its neighbour by FOLD_HOLD_PX.
 */
export function foldOverlaps(items: readonly FoldItem[], boxOf: (total: number, others: number) => [number, number], held: (key: string) => boolean = () => false): Map<string, Fold> {
  interface Group {
    it: FoldItem;
    total: number;
    nations: Set<number>;
    members: string[];
    w: number;
    h: number;
  }
  const size = (g: Group): Group => {
    [g.w, g.h] = boxOf(g.total, g.nations.size - 1);
    return g;
  };
  /** Greedy passes over `groups` in their order, until no box touches another it may fold into. */
  const settle = (groups: Group[], sameNationOnly: boolean): Group[] => {
    let free = groups;
    for (let merged = true; merged; ) {
      merged = false;
      const placed: Group[] = [];
      for (const g of free) {
        const pad = FOLD_GAP_PX + (held(g.it.key) ? FOLD_HOLD_PX : 0);
        let hit: Group | null = null;
        let nearest = Infinity;
        for (const p of placed) {
          if (sameNationOnly && p.it.nation !== g.it.nation) continue;
          const dx = Math.abs(p.it.x - g.it.x);
          const dy = Math.abs(p.it.y - g.it.y);
          if (dx >= (p.w + g.w) / 2 + pad || dy >= (p.h + g.h) / 2 + pad) continue;
          if (dx * dx + dy * dy < nearest) {
            nearest = dx * dx + dy * dy;
            hit = p;
          }
        }
        if (!hit) {
          placed.push(g);
          continue;
        }
        hit.total += g.total;
        for (const n of g.nations) hit.nations.add(n);
        hit.members.push(g.it.key, ...g.members);
        size(hit);
        merged = true;
      }
      free = placed;
    }
    return free;
  };
  const byKey = (a: Group, b: Group): number => (a.it.key < b.it.key ? -1 : 1);
  const own = items.map((it) => size({ it, total: it.strength, nations: new Set([it.nation]), members: [], w: 0, h: 0 })).sort((a, b) => b.total - a.total || byKey(a, b));
  const nations = settle(own, true).sort((a, b) => b.total - a.total || byKey(a, b));
  const lead = new Map<string, { lead: string; own: number }>();
  for (const g of nations) {
    lead.set(g.it.key, { lead: g.it.key, own: g.total });
    for (const k of g.members) lead.set(k, { lead: g.it.key, own: 0 });
  }
  const out = new Map<string, Fold>();
  for (const g of settle(nations, false)) {
    out.set(g.it.key, { into: null, total: g.total, others: g.nations.size - 1, ...lead.get(g.it.key)! });
    for (const k of g.members) out.set(k, { into: g.it.key, total: 0, others: 0, ...lead.get(k)! });
  }
  return out;
}

export class CounterLayer {
  level: number | null = null;
  private trans: { from: number; to: number; start: number } | null = null;
  /**
   * Per counter, its place in the declutter (PLAN 1.45b): folded into a neighbour or shown, since
   * `since`. A change is a fade in place over FOLD_MS: at rest a counter is shown in full or not
   * at all.
   */
  private folds = new Map<string, { folded: boolean; since: number }>();
  /** The counters of the last frame, in cells, with their fold state and the opacity it gave. */
  private last: { key: string; nation: number; x: number; y: number; state: { folded: boolean; since: number }; alpha: number }[] = [];
  /**
   * The hold of the declutter (PLAN 1.45b): the counters that were folded in the last frame, with
   * the layer at rest. Such a counter comes out only once it clears its neighbour by
   * FOLD_HOLD_PX more, so one at the edge does not flicker while the armies move.
   *
   * It is a memory of the layer at rest (PLAN 2.7l, ADR-75). A split or merge in flight is
   * folded without it and leaves none: its counters land free and are folded there by where
   * they stand, as in a view opened at that zoom. Kept through the flight, the hold recorded
   * which counters had touched which on the way, and that depends on the frames drawn: the same
   * step of the camera ended with other counters shown when its frames were further apart.
   *
   * And of one zoom (PLAN 3.5i, ADR-158): the first frame at another zoom is folded without it.
   * The hold is there for armies that move, and a step of the zoom moves none. Kept through a
   * step inside a level's band, it held counters that had room at the new zoom, and a counter
   * that came out could take a shown neighbour with it: fewer counters after a zoom in, and
   * not those of a view opened there.
   */
  /** The ball look's chips, drawn once each (PLAN 7.181). */
  private readonly ballCache = new Ball2dCache();
  /**
   * The heroes' counters as pictures (PLAN 7.184b3), each drawn once at its device scale and copied: painted
   * anew each frame, the 14 boxes at twice the size cost bench G's T0 5 % of its frames (ADR-789).
   */
  private readonly heroPictures = new Map<string, { flag: CanvasImageSource | null; canvas: HTMLCanvasElement; pad: number }>();
  private hold = new Set<string>();
  /** The zoom (px per cell) of the frame that left `hold`. */
  private holdScale: number | null = null;
  /** When the latest fold or unfold began. */
  private foldStart = -Infinity;
  /** Counters drawn last frame (tests). */
  drawn: DrawnCounter[] = [];
  /** Every box drawn last frame, CSS px: one per copy of a counter on a looping map (capital flags keep clear of them). */
  /** `alpha`: the opacity drawn; `own`: the counter's own part of it, without the layer's (a fold or a split in flight). */
  boxes: { x: number; y: number; w: number; h: number; alpha: number; own: number }[] = [];

  /** Every counter of the last frame, in cells, shown or folded into a neighbour (tests): the clusters of the level. */
  get laidOut(): readonly { key: string; x: number; y: number; folded: boolean }[] {
    return this.last.map((o) => ({ key: o.key, x: o.x, y: o.y, folded: o.state.folded }));
  }

  /** True while a split/merge or a fold animation runs (the view keeps redrawing). */
  animating(now: number): boolean {
    return (this.trans !== null && running(now, this.trans.start, SPLIT_MS)) || running(now, this.foldStart, FOLD_MS);
  }

  /**
   * Declutters `items` (already laid out, in cells) at `scale` px per cell and returns what to
   * draw at `now`: the shown counters with their totals, and those still fading out into a
   * neighbour or back in. `boxOf` as in `foldOverlaps`. `flying`: the items are those of a split
   * or merge on their way (no hold: see `hold`).
   */
  fold(
    items: readonly { key: string; c: Cluster; x: number; y: number }[],
    scale: number,
    now: number,
    boxOf: (total: number, others: number) => [number, number],
    flying = false,
    /** On a looping map, its width and the camera's x: each counter is folded at its copy nearest the camera (PLAN 7.4f43). */
    wrap?: { w: number; cx: number },
  ): { key: string; nation: number; x: number; y: number; alpha: number; strength: number; others: number; folded: boolean }[] {
    const stepped = !flying && scale !== this.holdScale;
    if (flying || stepped) this.hold.clear();
    const near = (a: { x: number; y: number }, b: { x: number; y: number }): boolean => Math.abs(a.x - b.x) * scale <= INHERIT_PX && Math.abs(a.y - b.y) * scale <= INHERIT_PX;
    // At the end of a split or merge a cluster and its children swap in the same place, under
    // new keys. A counter with a new key takes over the state of the counter of its nation that
    // stood there, the most visible one: a fade goes on through the swap.
    const at = new Map(items.map((it) => [it.key, it]));
    const fresh = new Set<string>();
    for (const it of items) {
      if (this.folds.has(it.key)) continue;
      fresh.add(it.key);
      let heir: (typeof this.last)[number] | null = null;
      for (const o of this.last) if (o.nation === it.c.nation && near(o, it) && (!heir || o.alpha > heir.alpha)) heir = o;
      if (!heir) continue;
      this.folds.set(it.key, { ...heir.state });
      if (this.hold.has(heir.key)) this.hold.add(it.key);
    }
    for (const key of this.folds.keys()) if (!at.has(key)) this.folds.delete(key);
    // At the copy nearest the camera (PLAN 7.4f43): two counters either side of the seam stand side
    // by side on the screen and a map's width apart in its cells; they were never folded.
    const near0 = (x: number): number => (wrap ? x + wrap.w * Math.round((wrap.cx - x) / wrap.w) : x);
    const boxes = items.map((it) => ({ key: it.key, nation: it.c.nation, x: near0(it.x) * scale, y: it.y * scale, strength: it.c.strength }));
    let result = foldOverlaps(boxes, boxOf, (key) => this.hold.has(key));
    // The frame of a step of the zoom is folded as the frames after it would be, one by one, each
    // with the hold of the one before, until the fold stands: every counter that turns, turns now.
    for (let round = 0; stepped && round < STEP_ROUNDS; round++) {
      const before = result;
      result = foldOverlaps(boxes, boxOf, (key) => before.get(key)!.into !== null);
      if (boxes.every((b) => result.get(b.key)!.into === before.get(b.key)!.into)) break;
    }
    const hold = new Set<string>();
    const out: { key: string; nation: number; x: number; y: number; alpha: number; strength: number; others: number; folded: boolean }[] = [];
    const seen: typeof this.last = [];
    let latest = -Infinity;
    for (const it of items) {
      const f = result.get(it.key)!;
      const folded = f.into !== null;
      const lead = f.lead !== it.key ? at.get(f.lead) : undefined;
      let st = this.folds.get(it.key);
      if (!st || (fresh.has(it.key) && lead !== undefined && near(lead, it))) {
        // A counter new to the map takes its place at once. So does a new one standing on the
        // counter of its nation that stands for them both (the children of a cluster, on its
        // centroid when a split begins): it is inside that one from the start.
        st = { folded, since: -Infinity };
      } else if (st.folded !== folded) {
        // A turn in mid-fade goes on from the opacity reached.
        st = { folded, since: now - (1 - progress(now, st.since, FOLD_MS)) * FOLD_MS };
      }
      this.folds.set(it.key, st);
      if (st.since <= now && st.since > latest) latest = st.since;
      const p = ease(progress(now, st.since, FOLD_MS));
      const alpha = st.folded ? 1 - p : p;
      if (folded && !flying) hold.add(it.key);
      seen.push({ key: it.key, nation: it.c.nation, x: it.x, y: it.y, state: st, alpha });
      if (alpha <= 0) continue; // folded: its strength is in its neighbour's number
      // A shown counter shows all it holds; one fading out, what it holds of its own nation.
      out.push({ key: it.key, nation: it.c.nation, x: it.x, y: it.y, alpha, strength: !folded ? f.total : f.lead === it.key ? f.own : it.c.strength, others: folded ? 0 : f.others, folded });
    }
    this.last = seen;
    this.hold = hold;
    this.holdScale = scale;
    this.foldStart = latest;
    return out;
  }

  /**
   * What `draw` draws at `now`: the counters laid out and decluttered. Nothing when the layer
   * is not visible or the map has no formation.
   */
  declutter(
    src: readonly CounterSource[],
    scale: number,
    now: number,
    visible: boolean,
    boxOf: (total: number, others: number) => [number, number],
    wrap?: { w: number; cx: number },
  ): ReturnType<CounterLayer['fold']> {
    const items = this.layout(src, scale, now, visible);
    if (items.length === 0) {
      // Nothing on the map: the next counters take their places at once.
      this.folds.clear();
      this.last = [];
      this.hold.clear();
      return [];
    }
    return this.fold(items, scale, now, boxOf, this.trans !== null, wrap);
  }

  /** The counters to show at `now`: positions in cells, after any animation. */
  layout(src: readonly CounterSource[], scale: number, now: number, visible: boolean): { key: string; c: Cluster; x: number; y: number }[] {
    if (this.trans && progress(now, this.trans.start, SPLIT_MS) >= 1) {
      this.level = this.trans.to;
      this.trans = null;
    }
    // The level wanted, judged against the level held now. (Judged against the level a finished
    // change has just left, a zoom inside the bands of both sent it back, and back again: PLAN 2.7f.)
    const target = clusterLevel(scale, this.level);
    if (!visible || this.level === null) {
      // Invisible: follow the zoom without animating.
      this.level = target;
      this.trans = null;
      if (!visible) return [];
    }
    if (!this.trans && target !== this.level) this.trans = { from: this.level!, to: target, start: now };
    if (!this.trans) {
      return [...buildClusters(src, this.level!).entries()].map(([key, c]) => ({ key, c, x: c.x, y: c.y }));
    }
    const { from, to, start } = this.trans;
    const fine = Math.min(from, to);
    const coarse = Math.max(from, to);
    const d = coarse - fine;
    const p = ease(progress(now, start, SPLIT_MS));
    const s = to < from ? 1 - p : p; // 1 = at the parent's centroid
    const parents = buildClusters(src, coarse);
    return [...buildClusters(src, fine).entries()].map(([key, c]) => {
      const par = parents.get(clusterKey(c.nation, coarse, Math.floor(c.gx / 2 ** d), Math.floor(c.gy / 2 ** d)))!;
      return { key, c, x: c.x + (par.x - c.x) * s, y: c.y + (par.y - c.y) * s };
    });
  }

  draw(
    ctx: CanvasRenderingContext2D,
    src: readonly CounterSource[],
    cam: Camera,
    geo: MapGeometry,
    vw: number,
    vh: number,
    alpha: number,
    now: number,
    colorOf: (nation: number) => string,
    flagOf: (nation: number) => CanvasImageSource | null,
    /** Unit-size setting (PLAN 1.39a): scales each counter about its position. */
    size = 1,
    /** The ball look (PLAN 7.174f): the flag chip a countryball. */
    balls = false,
    /** The heroes (PLAN 7.184b3), not in `src`: each its own counter, never folded, above the others. */
    heroes: readonly HeroCounter[] = [],
  ): void {
    this.drawn = [];
    this.boxes = [];
    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.font = '700 10px system-ui, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    const widths = new Map<string, number>();
    const widthOf = (text: string): number => {
      let w = widths.get(text);
      if (w === undefined) widths.set(text, (w = Math.ceil(ctx.measureText(text).width)));
      return w;
    };
    const h = 14;
    // Flag chip, the strength, and "+n" for the other nations folded in.
    const boxWidth = (strength: number, others: number): number => widthOf(strengthText(strength)) + 18 + (others > 0 ? widthOf(`+${others}`) + BADGE_GAP : 0);
    const shown = this.declutter(src, cam.scale, now, alpha > 0.01, (total, others) => [boxWidth(total, others) * size, h * size], geo.wrapX ? { w: geo.w, cx: cam.cx } : undefined);
    const offs = itemOffsets(cam, geo, vw);
    // Small first, so the big stacks stay on top.
    shown.sort((a, b) => a.strength - b.strength || (a.key < b.key ? -1 : 1));
    for (const it of shown) {
      const a = alpha * it.alpha;
      if (a <= 0.01) continue;
      const naval = it.nation >= NAVAL;
      const nation = naval ? it.nation - NAVAL : it.nation;
      const text = strengthText(it.strength);
      const w = boxWidth(it.strength, it.others);
      let box: [number, number] | null = null;
      for (const off of offs) {
        const [sx, sy] = worldToScreen(cam, it.x + off, it.y, vw, vh);
        const x = Math.round(sx - w / 2);
        const y = Math.round(sy - h / 2);
        if (sx - (w / 2) * size > vw || sy - (h / 2) * size > vh || sx + (w / 2) * size < 0 || sy + (h / 2) * size < 0) continue;
        box ??= [sx + (x - sx) * size, sy + (y - sy) * size];
        this.boxes.push({ x: sx + (x - sx) * size, y: sy + (y - sy) * size, w: w * size, h: h * size, alpha: a, own: it.alpha });
        this.paint(ctx, sx, sy, x, y, w, h, size, a, naval, nation, text, it.others, widthOf, colorOf, flagOf, balls);
      }
      if (box) this.drawn.push({ key: it.key, nation, naval, wx: it.x, wy: it.y, alpha: a, strength: it.strength, text, others: it.others, folded: it.folded, x: box[0], y: box[1], w: w * size, h: h * size });
    }
    // The heroes (PLAN 7.184b3): each its own counter about its place, HERO_SCALE × the size, its name for
    // its strength; never folded into its nation's, and above them. One that would cover another hero's
    // (Japan's two, at Yokosuka and Tokyo) steps one height down, else one up; else it is folded into the
    // hero counter of its nation it covers, which reads "Char 2C +2" and opens its heroes in turn (ROADMAP
    // R8, R29-B1); with none of its nation, at the one of those three steps that covers the least of the
    // others (ROADMAP R14, R30-B1:
    // HMS Hood was folded into "Sovetsky Soyuz +1", under the Soviet flag ~2,900 km from itself).
    // Stepped down as often as it took, Europe's ten heroes at the world's zoom cascaded into Africa,
    // P.100 Ercole drawn 5,009 km from itself. Laid out once, on the first copy; each copy drawn, a
    // counter whose place is in the view kept whole in it ("+1" was cut by the screen's edge).
    const hs = size * HERO_SCALE;
    if (alpha > 0.01) {
      const step = (h + 2) * hs;
      const groups: { lead: HeroCounter; members: number[]; dy: number; box: [number, number, number, number] }[] = [];
      const over = (a: [number, number, number, number], x: number, y: number, w: number, hh: number): boolean => !(x >= a[0] + a[2] || x + w <= a[0] || y >= a[1] + a[3] || y + hh <= a[1]);
      for (const hero of heroes) {
        const w = widthOf(hero.name) + 18;
        const [sx, sy0] = worldToScreen(cam, hero.x, hero.y, vw, vh);
        const boxAt = (dy: number): [number, number, number, number] => [sx - (w / 2) * hs, sy0 + dy - (h / 2) * hs, w * hs, h * hs];
        const dy = [0, step, -step].find((d) => groups.every((g) => !over(g.box, ...boxAt(d))));
        if (dy !== undefined) {
          groups.push({ lead: hero, members: [hero.id], dy, box: boxAt(dy) });
          continue;
        }
        const mine = (g: (typeof groups)[number]): boolean => g.lead.nation === hero.nation;
        const host = groups.find((g) => mine(g) && over(g.box, ...boxAt(0))) ?? groups.find((g) => mine(g) && over(g.box, ...boxAt(step)));
        if (host) {
          host.members.push(hero.id);
          continue;
        }
        // None of its nation: at the step of the three that covers the least of the others.
        const cover = (d: number): number => {
          const [x, y, bw, bh] = boxAt(d);
          let sum = 0;
          for (const g of groups) sum += Math.max(0, Math.min(x + bw, g.box[0] + g.box[2]) - Math.max(x, g.box[0])) * Math.max(0, Math.min(y + bh, g.box[1] + g.box[3]) - Math.max(y, g.box[1]));
          return sum;
        };
        const least = [0, step, -step].reduce((a, d) => (cover(d) < cover(a) ? d : a));
        groups.push({ lead: hero, members: [hero.id], dy: least, box: boxAt(least) });
      }
      for (const g of groups) {
        const name = g.members.length > 1 ? `${g.lead.name} +${g.members.length - 1}` : g.lead.name;
        const w = widthOf(name) + 18;
        let box: [number, number] | null = null;
        for (const off of offs) {
          const [sx, sy0] = worldToScreen(cam, g.lead.x + off, g.lead.y, vw, vh);
          let sx1 = sx;
          const sy = sy0 + g.dy;
          if (sx - (w / 2) * hs > vw || sy - (h / 2) * hs > vh || sx + (w / 2) * hs < 0 || sy + (h / 2) * hs < 0) continue;
          // The box is rounded before it is scaled: a margin of `hs` keeps the rounding inside the view.
          if (sx >= 0 && sx <= vw) sx1 = Math.min(Math.max(sx, (w / 2 + 1) * hs), vw - (w / 2 + 1) * hs);
          const x = Math.round(sx1 - w / 2);
          const y = Math.round(sy - h / 2);
          box ??= [sx1 + (x - sx1) * hs, sy + (y - sy) * hs];
          this.boxes.push({ x: sx1 + (x - sx1) * hs, y: sy + (y - sy) * hs, w: w * hs, h: h * hs, alpha, own: 1 });
          this.paintHero(ctx, sx1 + (x - sx1) * hs, sy + (y - sy) * hs, w, h, hs, alpha, { ...g.lead, name }, widthOf, colorOf, flagOf, balls);
        }
        if (box) this.drawn.push({ key: `hero:${g.lead.id}`, nation: g.lead.nation, naval: g.lead.naval, wx: g.lead.x, wy: g.lead.y, alpha, strength: 0, text: name, others: g.members.length - 1, folded: false, x: box[0], y: box[1], w: w * hs, h: h * hs, hero: g.lead.id, heroes: g.members });
      }
    }
    ctx.restore();
  }

  /** A hero's counter, its box's corner at (bx, by) CSS px and `size`, from its picture (`heroPictures`). */
  private paintHero(
    ctx: CanvasRenderingContext2D,
    bx: number,
    by: number,
    w: number,
    h: number,
    size: number,
    alpha: number,
    hero: HeroCounter,
    widthOf: (text: string) => number,
    colorOf: (nation: number) => string,
    flagOf: (nation: number) => CanvasImageSource | null,
    balls: boolean,
  ): void {
    const m = ctx.getTransform();
    const flag = flagOf(hero.nation);
    const tint = colorOf(hero.nation);
    if (typeof document === 'undefined' || m.b !== 0 || m.c !== 0 || m.a <= 0 || m.a !== m.d) {
      this.paint(ctx, bx, by, bx, by, w, h, size, alpha, hero.naval, hero.nation, hero.name, 0, widthOf, colorOf, flagOf, balls);
      return;
    }
    const k = m.a * size;
    const key = `${hero.id}|${hero.name}|${hero.naval ? 1 : 0}|${tint}|${balls ? 1 : 0}|${k}`;
    let pic = this.heroPictures.get(key);
    if (!pic || pic.flag !== flag) {
      // The ball overhangs the box's left end by a px or two (COUNTER_BALL_R about its chip).
      const pad = 3;
      const canvas = document.createElement('canvas');
      canvas.width = Math.ceil((w + 2 * pad) * k);
      canvas.height = Math.ceil((h + 2 * pad) * k);
      const g = canvas.getContext('2d')!;
      g.setTransform(k, 0, 0, k, pad * k, pad * k);
      g.imageSmoothingEnabled = false;
      g.font = ctx.font;
      g.textAlign = 'left';
      g.textBaseline = 'middle';
      this.paint(g, 0, 0, 0, 0, w, h, 1, 1, hero.naval, hero.nation, hero.name, 0, widthOf, colorOf, flagOf, balls);
      if (this.heroPictures.size > 256) this.heroPictures.clear();
      this.heroPictures.set(key, (pic = { flag, canvas, pad }));
    }
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = alpha;
    ctx.drawImage(pic.canvas, Math.round(m.a * bx + m.e - pic.pad * k), Math.round(m.d * by + m.f - pic.pad * k));
    ctx.restore();
  }

  /** One counter's box, about (sx, sy) at `size`: its flag chip (or ball), frame, a navy's hull, its text and "+n". */
  private paint(
    ctx: CanvasRenderingContext2D,
    sx: number,
    sy: number,
    x: number,
    y: number,
    w: number,
    h: number,
    size: number,
    a: number,
    naval: boolean,
    nation: number,
    text: string,
    others: number,
    widthOf: (text: string) => number,
    colorOf: (nation: number) => string,
    flagOf: (nation: number) => CanvasImageSource | null,
    balls: boolean,
  ): void {
    ctx.save();
    ctx.globalAlpha = a;
    if (size !== 1) {
      ctx.translate(sx, sy);
      ctx.scale(size, size);
      ctx.translate(-sx, -sy);
    }
    // A navy's counter (PLAN 4.10a): a sea-blue box and frame with a hull under its strength.
    ctx.fillStyle = naval ? 'rgba(14, 38, 72, 0.9)' : 'rgba(16, 18, 24, 0.85)';
    ctx.fillRect(x, y, w, h);
    const flag = flagOf(nation);
    if (!balls) {
      ctx.fillStyle = colorOf(nation);
      ctx.fillRect(x + 1, y + 1, 12, h - 2);
      if (flag) ctx.drawImage(flag, x + 2, y + 3, 10, 8);
    }
    ctx.strokeStyle = naval ? '#8ec5ff' : 'rgba(0, 0, 0, 0.9)';
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
    // In the ball look the chip is a countryball over the box's left end (a fleet's hull is the box's own).
    if (balls) drawBall2dCached(ctx, this.ballCache, x + 7, y + h / 2, COUNTER_BALL_R, { flag, tint: colorOf(nation), look: 1, prop: 'none' });
    if (naval) {
      ctx.fillStyle = '#8ec5ff';
      ctx.beginPath();
      ctx.moveTo(x + 14, y + h - 4);
      ctx.lineTo(x + w - 2, y + h - 4);
      ctx.lineTo(x + w - 5, y + h - 2);
      ctx.lineTo(x + 16, y + h - 2);
      ctx.closePath();
      ctx.fill();
    }
    ctx.fillStyle = naval ? '#d6ecff' : '#ffe28a';
    ctx.fillText(text, x + 15, y + h / 2 + (naval ? -0.5 : 0.5));
    if (others > 0) {
      ctx.fillStyle = '#b4bdcb';
      ctx.fillText(`+${others}`, x + 15 + widthOf(text) + BADGE_GAP, y + h / 2 + 0.5);
    }
    ctx.restore();
  }
}
